--- a/redwood/serve/prefill_manager.cc
+++ b/redwood/serve/prefill_manager.cc
@@ -120,6 +120,28 @@
-  // previous monolithic prefill loop
+  // new chunked prefill: break long prefill into smaller KV-populate chunks
+  for (auto &chunk : chunked_iterator(request.prefill_tokens, chunk_size)) {
+    populate_kv_cache(chunk);
+    if (should_yield_to_decode()) {
+      scheduler.try_schedule_decode_ready(request);
+    }
+  }

--- a/runtime/kv_cache.cc
+++ b/runtime/kv_cache.cc
@@ -45,6 +45,18 @@
+// Introduce sync points when stage overlap is enabled to keep KV writes visible
+void KVCache::publish_chunk(const ChunkMeta &m) {
+  std::unique_lock lk(mu_);
+  apply_entries(m.entries);
+  // publish a lightweight versioned marker for readers
+  version_.fetch_add(1, std::memory_order_release);
+}

--- a/runtime/kernel_scheduler.cc
